public static void fillArrayANDNOT(final char[] container, final long[] bitmap1, final long[] bitmap2) {
    int pos = 0;
    if (bitmap1.length != bitmap2.length) {
        throw new IllegalArgumentException("not supported");
    }
    for (int k = 0; k < bitmap1.length; ++k) {
        long bitset = bitmap1[k] & (~bitmap2[k]);
        if (bitset == 0) continue;
        int base = k << 6; // k * 64
        while (bitset != 0) {
            int tz = Long.numberOfTrailingZeros(bitset);
            container[pos++] = (char) (base + tz);
            bitset &= bitset - 1;
        }
    }
}

