private boolean parse1(CharSequence txt, int start, int end) {
    int tokenStart = -1;

    for (int i = start; i < end; i++) {
        char c = txt.charAt(i);
        // RFC6265 delimiters, represented by two 64-bit masks.
        boolean delimiter = c < 64
                ? (0xF800FFFF00000200L & (1L << c)) != 0
                : c < 128 && (0x78000001F8000001L & (1L << (c - 64))) != 0;

        if (delimiter) {
            if (tokenStart != -1) {
                if (parseToken(txt, tokenStart, i)) {
                    return true;
                }
                tokenStart = -1;
            }
        } else if (tokenStart == -1) {
            tokenStart = i;
        }
    }

    return tokenStart != -1 && parseToken(txt, tokenStart, end);
}

