public static int advanceUntil(char[] array, int pos, int length, char min) {
    int lower = pos + 1;

    if (lower >= length || array[lower] >= min) {
      return lower;
    }

    int spansize = 1;
    int upper;
    char upperValue;
    while (true) {
      upper = lower + spansize;
      if (upper >= length) {
        upper = length - 1;
        upperValue = array[upper];
        break;
      }
      upperValue = array[upper];
      if (upperValue >= min) {
        break;
      }
      spansize *= 2;
    }

    if (upperValue == min) {
      return upper;
    }
    if (upperValue < min) {
      return length;
    }

    lower += spansize >>> 1;
    while (lower + 1 != upper) {
      int mid = (lower + upper) >>> 1;
      char arraymid = array[mid];
      if (arraymid == min) {
        return mid;
      } else if (arraymid < min) {
        lower = mid;
      } else {
        upper = mid;
      }
    }
    return upper;
  }

