        if (c != ':') {
            int digit = c - '0';
            if (digit < 0 || digit > 9) {
                return false;
            }
            localMinutes = localMinutes * 10 + digit;
            if (i >= tokenEnd || txt.charAt(i++) != ':') {
                return false;
            }
        }

        int remaining = tokenEnd - i;
        if (remaining < 1 || remaining > 2) {
            return false;
        }
        int localSeconds = txt.charAt(i++) - '0';
        if (localSeconds < 0 || localSeconds > 9) {
