    if (len < 5 || len > 8) {
        return false;
    }

    int i = tokenStart;
    char c = txt.charAt(i++);
    if (!isDigit(c)) {
        return false;
    }
    int localHours = getNumericalValue(c);
    c = txt.charAt(i++);
    if (isDigit(c)) {
        localHours = localHours * 10 + getNumericalValue(c);
        c = txt.charAt(i++);
    }
    if (c != ':') {
        return false;
    }

    c = txt.charAt(i++);
    if (!isDigit(c)) {
        return false;
    }
    int localMinutes = getNumericalValue(c);
    c = txt.charAt(i++);
    if (isDigit(c)) {
        localMinutes = localMinutes * 10 + getNumericalValue(c);
        if (i == tokenEnd) {
            return false;
        }
        c = txt.charAt(i++);
    }
    if (c != ':') {
        return false;
    }

    int remaining = tokenEnd - i;
    if (remaining < 1 || remaining > 2) {
        return false;
    }
    c = txt.charAt(i++);
    if (!isDigit(c)) {
        return false;
    }
    int localSeconds = getNumericalValue(c);
    if (remaining == 2) {
        c = txt.charAt(i);
        if (!isDigit(c)) {
            return false;
        }
        localSeconds = localSeconds * 10 + getNumericalValue(c);
    }

    hours = localHours;
    minutes = localMinutes;
    seconds = localSeconds;
    return true;
}

