protected static int unsignedOneSidedGallopingIntersect2by2(
      final char[] smallSet,
      final int smallLength,
      final char[] largeSet,
      final int largeLength,
      final char[] buffer) {
    if (0 == smallLength) {
      return 0;
    }
    int k1 = 0;
    int k2 = 0;
    int pos = 0;
    char s1 = largeSet[k1];
    char s2 = smallSet[k2];
