        }
        s1 = largeSet[k1];
      }
      if (s2 < s1) {
        ++k2;
        if (k2 == smallLength) {
          break;
        }
        s2 = smallSet[k2];
      } else {
        // equal: emit and move on; the next iteration's s1 < s2 check does the gallop
