private boolean parse1(CharSequence txt, int start, int end) {
        // return true if all parts are found
        final long lo = 0xF800FFFF00000200L;
        final long hi = 0x78000001F8000001L;
        int tokenStart = -1;

        for (int i = start; i < end; i++) {
            char c = txt.charAt(i);
            boolean delim;
            if (c < 64) {
                delim = ((lo >>> c) & 1L) != 0;
            } else if (c < 128) {
                delim = ((hi >>> (c - 64)) & 1L) != 0;
            } else {
                delim = false;
            }

            if (delim) {
                if (tokenStart != -1) {
                    // terminate token
                    if (parseToken(txt, tokenStart, i)) {
                        return true;
                    }
                    tokenStart = -1;
                }
            } else if (tokenStart == -1) {
                // start new token
                tokenStart = i;
            }
        }

        // terminate trailing token at end, not txt.length(), so a substring parse doesn't overrun
        return tokenStart != -1 && parseToken(txt, tokenStart, end);
    }

