public static int advanceUntil(char[] array, int pos, int length, char min) {
    int lower = pos + 1;

    // special handling for a possibly common sequential case
    if (lower >= length || array[lower] >= min) {
      return lower;
    }

    int spansize = 1;
    // bootstrap an upper limit (galloping)
    while (lower + spansize < length && array[lower + spansize] < min) {
      spansize <<= 1;
    }
    int upper = (lower + spansize < length) ? lower + spansize : length - 1;

    if (array[upper] < min) {
      // no item >= min
      return length;
    }

    // we know that the next-smallest span was too small
    lower += (spansize >>> 1);

    // binary search; invariant: array[lower] < min && array[upper] >= min
    while (lower + 1 != upper) {
      int mid = (lower + upper) >>> 1;
      if (array[mid] < min) {
        lower = mid;
      } else {
        upper = mid;
      }
    }
    return upper;
  }

