public void addN(final int[] dat, final int offset, final int n) {
    // let us validate the values first.
    if ((n < 0) || (offset < 0)) {
      throw new IllegalArgumentException("Negative values do not make sense.");
    }
    if (n == 0) {
      return; // nothing to do
    }
    if (offset + n > dat.length) {
      throw new IllegalArgumentException("Data source is too small.");
    }
    final int end = offset + n;
    int i = offset;
    while (i < end) {
      int val = dat[i];
      final char hb = Util.highbits(val);
      int idx = highLowContainer.getIndex(hb);
      Container cont;
      if (idx >= 0) {
        cont = highLowContainer.getContainerAtIndex(idx);
        Container newcont = cont.add(Util.lowbits(val));
        if (newcont != cont) {
          highLowContainer.setContainerAtIndex(idx, newcont);
          cont = newcont;
        }
      } else {
        idx = -idx - 1;
        final ArrayContainer newac = new ArrayContainer();
        cont = newac.add(Util.lowbits(val));
        highLowContainer.insertNewKeyValueAt(idx, hb, cont);
      }
      i++;
      // tight loop over consecutive values sharing the same high bits
      while (i < end) {
        val = dat[i];
        if (Util.highbits(val) != hb) {
          break;
        }
        Container newcont = cont.add(Util.lowbits(val));
        if (newcont != cont) {
          highLowContainer.setContainerAtIndex(idx, newcont);
          cont = newcont;
        }
        i++;
      }
    }
  }

