public void addN(final int[] dat, final int offset, final int n) {
    // let us validate the values first.
    if ((n < 0) || (offset < 0)) {
      throw new IllegalArgumentException("Negative values do not make sense.");
    }
    if (n == 0) {
      return; // nothing to do
    }
    if (offset + n > dat.length) {
      throw new IllegalArgumentException("Data source is too small.");
    }
    final RoaringArray hlc = this.highLowContainer;
    final int end = offset + n;
    int j = offset;
    while (j < end) {
      int val = dat[j];
      final int hb = val >>> 16;
      final char hbc = (char) hb;
      int idx = hlc.getIndex(hbc);
      Container cont;
      if (idx >= 0) {
        cont = hlc.getContainerAtIndex(idx);
        Container nc = cont.add(Util.lowbits(val));
        if (nc != cont) {
          hlc.setContainerAtIndex(idx, nc);
          cont = nc;
        }
      } else {
        idx = -idx - 1;
        final ArrayContainer newac = new ArrayContainer();
        cont = newac.add(Util.lowbits(val));
        hlc.insertNewKeyValueAt(idx, hbc, cont);
      }
      j++;
      // tight loop over the values sharing the same high 16 bits
      while (j < end) {
        val = dat[j];
        if ((val >>> 16) != hb) {
          break;
        }
        Container nc = cont.add(Util.lowbits(val));
        if (nc != cont) {
          hlc.setContainerAtIndex(idx, nc);
          cont = nc;
        }
        j++;
      }
    }
  }

