    int low = begin;
    int high = end;
    // lower-bound search without the equality early exit: one comparison per step
    while (high - low > 32) {
      final int middle = (low + high) >>> 1;
      if (array[middle] < k) {
        low = middle + 1;
      } else {
        high = middle;
      }
    }
    // finish with a sequential scan
    while (low < high && array[low] < k) {
      low++;
    }
    if (low < end && array[low] == k) {
      return low;
    }
    return -(low + 1);
  }

