@Override
  protected BranchNode insert(Node childNode, byte key) {
    int n = this.count;
    if (n < 4) {
      // insert in sorted position directly on the packed int key, no temporary arrays
      int keyInt = this.key;
      int ku = key & 0xFF;
      Node[] ch = this.children;
