                // all other destroyChunk calls come from the arena itself being finalized, so don't need to be counted
                ++pooledChunkDeallocations;
            }
        } finally {
            unlock();
        }
        if (destroyChunk) {
            // destroyChunk not need to be called while holding the synchronized lock.
            destroyChunk(chunk);
        }
    }

