protected static int hybridUnsignedBinarySearch(
      final char[] array, final int begin, final int end, final char k) {
    // next line accelerates the possibly common case where the value would
    // be inserted at the end
    if ((end > 0) && ((array[end - 1]) < (int) k)) {
      return -end - 1;
    }
    int low = begin;
    int high = end;
    final int key = k;
    // lower-bound search without an equality branch; narrows to a small window
    while (high - low > 32) {
      final int middle = (low + high) >>> 1;
      if (array[middle] < key) {
        low = middle + 1;
      } else {
        high = middle;
      }
    }
    // finish with a sequential search
    while (low < high && array[low] < key) {
      low++;
    }
    if (low < end && array[low] == key) {
      return low;
    }
    return -(low + 1);
  }

