protected static int hybridUnsignedBinarySearch(
      final char[] array, final int begin, final int end, final char k) {
    // next line accelerates the possibly common case where the value would
    // be inserted at the end
    if ((end > 0) && ((array[end - 1]) < (int) k)) {
      return -end - 1;
    }
    int low = begin;
    int high = end; // exclusive upper bound of the lower-bound search
    // lower-bound search without an equality branch: one data-dependent branch per step
    while (high - low > 32) {
      final int middle = (low + high) >>> 1;
      if (array[middle] < k) {
        low = middle + 1;
      } else {
        high = middle;
      }
    }
    // finish with a sequential scan
    while (low < high && array[low] < k) {
      low++;
    }
    if (low < end && array[low] == k) {
      return low;
    }
    return -(low + 1);
  }

