public static SortedMap<Character, List<Container>> groupByKey(RoaringBitmap... bitmaps) {
    long containerCount = 0;
    int maxKey = -1;
    for (RoaringBitmap bitmap : bitmaps) {
      RoaringArray ra = bitmap.highLowContainer;
      containerCount += ra.size;
      if (ra.size != 0) {
        maxKey = Math.max(maxKey, ra.keys[ra.size - 1]);
      }
    }

    if (containerCount >= 1024 && containerCount >= (maxKey + 1L) / 4) {
      @SuppressWarnings("unchecked")
      List<Container>[] slices = (List<Container>[]) new List<?>[maxKey + 1];
      for (RoaringBitmap bitmap : bitmaps) {
        RoaringArray ra = bitmap.highLowContainer;
        for (int i = 0; i < ra.size; ++i) {
          int key = ra.keys[i];
          List<Container> slice = slices[key];
          if (slice == null) {
            slices[key] = slice = new ArrayList<>();
          }
          slice.add(ra.values[i]);
        }
      }
      SortedMap<Character, List<Container>> result = new TreeMap<>();
      for (int key = 0; key < slices.length; ++key) {
        if (slices[key] != null) {
          result.put((char) key, slices[key]);
        }
      }
      return result;
    }

    Map<Character, List<Container>> grouped = new HashMap<>();
    for (RoaringBitmap bitmap : bitmaps) {
      RoaringArray ra = bitmap.highLowContainer;
      for (int i = 0; i < ra.size; ++i) {
        Container container = ra.values[i];
        Character key = ra.keys[i];
        List<Container> slice = grouped.get(key);
        if (slice == null) {
          slice = new ArrayList<>();
          grouped.put(key, slice);
        }
        slice.add(container);
      }
    }
    return new TreeMap<>(grouped);
  }

