void reset() {
    long[] counters = table;
    @Var long count = 0;
    int i = 0;
    for (; i < counters.length - 3; i += 4) {
      long a = counters[i];
      long b = counters[i + 1];
      long c = counters[i + 2];
      long d = counters[i + 3];
      count += Long.bitCount(a & ONE_MASK)
          + Long.bitCount(b & ONE_MASK)
          + Long.bitCount(c & ONE_MASK)
          + Long.bitCount(d & ONE_MASK);
      counters[i] = (a >>> 1) & RESET_MASK;
      counters[i + 1] = (b >>> 1) & RESET_MASK;
      counters[i + 2] = (c >>> 1) & RESET_MASK;
      counters[i + 3] = (d >>> 1) & RESET_MASK;
    }
    for (; i < counters.length; i++) {
      long value = counters[i];
      count += Long.bitCount(value & ONE_MASK);
      counters[i] = (value >>> 1) & RESET_MASK;
    }
    size = Math.max(0, (int) ((size - (count >>> 2)) >>> 1));
  }

