private static int horizontalOrCardinality(ImmutableRoaringBitmap... bitmaps) {
    long[] words = new long[1024];
    int[] indexes = new int[bitmaps.length];
    int key = 1 << 16;
    for (ImmutableRoaringBitmap bitmap : bitmaps) {
      if (bitmap.highLowContainer.size() != 0) {
        key = Math.min(key, bitmap.highLowContainer.getKeyAtIndex(0));
      }
    }

    LongBuffer longBuffer = LongBuffer.wrap(words);
    int cardinality = 0;
    while (key < (1 << 16)) {
      Arrays.fill(words, 0);
      MappeableContainer tmp = new MappeableBitmapContainer(longBuffer, -1);
      int nextKey = 1 << 16;
      for (int i = 0; i < bitmaps.length; i++) {
        ImmutableRoaringBitmap bitmap = bitmaps[i];
        int index = indexes[i];
        int size = bitmap.highLowContainer.size();
        if (index >= size) {
          continue;
        }
        int bitmapKey = bitmap.highLowContainer.getKeyAtIndex(index);
        if (bitmapKey == key) {
          MappeableContainer container = bitmap.highLowContainer.getContainerAtIndex(index);
          MappeableContainer or = tmp.lazyIOR(container);
          if (or != tmp) {
            tmp = or;
          }
          indexes[i] = ++index;
          if (index >= size) {
            continue;
          }
          bitmapKey = bitmap.highLowContainer.getKeyAtIndex(index);
        }
        nextKey = Math.min(nextKey, bitmapKey);
      }
      cardinality += tmp.repairAfterLazy().getCardinality();
      key = nextKey;
    }
    return cardinality;
  }

