@SuppressWarnings("Varifier")
  int expire(BoundedLocalCache<K, V> cache, int index,
      long previousTicks, long delta, @Var int limit) {
    Node<K, V>[] timerWheel = wheel[index];
    int mask = timerWheel.length - 1;

    int steps = (int) Math.min(1 + delta, timerWheel.length);
    int start = (int) (previousTicks & mask);
    int end = start + steps;

    for (int i = start; i < end; i++) {
      Node<K, V> sentinel = timerWheel[i & mask];
      if ((sentinel.getNextInVariableOrder() == sentinel)
          && (pending.getNextInVariableOrder() == pending)) {
        if (limit <= 0) {
          return 0;
        }
        continue;
      }
      transfer(sentinel, pending);
      try {
        @Var Node<K, V> node;
        while ((node = pending.getNextInVariableOrder()) != pending) {
          deschedule(node);
          try {
            if ((node.getVariableTime() - nanos) > 0) {
              schedule(node);
            } else if (cache.evictEntry(node, RemovalCause.EXPIRED, nanos)) {
              limit--;
            } else {
              schedule(node);
            }
          } catch (Throwable t) {
            link(pending, node);
            throw t;
          }
        }
      } finally {
        transfer(pending, sentinel);
      }
      if (limit <= 0) {
        // Leave the remaining buckets for the next advance to process
        return 0;
      }
    }
    return limit;
  }

