public static void fillArrayANDNOT(
      final char[] container, final long[] bitmap1, final long[] bitmap2) {
    int pos = 0;
    final int len = bitmap1.length;
    if (len != bitmap2.length) {
      throw new IllegalArgumentException("not supported");
    }
