@SuppressWarnings("Varifier")
  int expire(BoundedLocalCache<K, V> cache, int index,
      long previousTicks, long delta, @Var int limit) {
    Node<K, V>[] timerWheel = wheel[index];
    int mask = timerWheel.length - 1;

    int steps = (int) Math.min(1 + delta, timerWheel.length);
    int start = (int) (previousTicks & mask);
    int end = start + steps;
    Node<K, V> pending = this.pending;
    long now = nanos;

    for (int i = start; i < end; i++) {
      Node<K, V> sentinel = timerWheel[i & mask];
      transfer(sentinel, pending);
      try {
        @Var Node<K, V> node;
        while ((node = pending.getNextInVariableOrder()) != pending) {
          // node is the head of the pending list, so unlink it directly
          Node<K, V> next = node.getNextInVariableOrder();
          pending.setNextInVariableOrder(next);
          next.setPreviousInVariableOrder(pending);
          node.setNextInVariableOrder(null);
          node.setPreviousInVariableOrder(null);
          try {
            if ((node.getVariableTime() - now) > 0) {
              schedule(node);
            } else if (cache.evictEntry(node, RemovalCause.EXPIRED, now)) {
              limit--;
            } else {
