      byte[] key, Node[] children, int left, int right) { // x
    for (int i = left; i < right; i++) {
      final byte ai = key[i + 1];
      final int unsignedAi = ai & 0xFF;
      int j = i;
      byte kj = key[j];
      if (unsignedAi >= (kj & 0xFF)) {
        continue;
      }
      final Node child = children[i + 1];
      while (true) {
        key[j + 1] = kj;
        children[j + 1] = children[j];
        j--;
        if (j < left) {
          break;
