            if (cIndex != lvProducerIndex())
            {
                do
                {
                    e = lvRefElement(buffer, offset);
                }
                while (e == null);
            }
            else
            {
                return null;
            }
        }

        spRefElement(buffer, offset, null);
        soConsumerIndex(cIndex + 1);
        return e;
    }

