private static int horizontalOrCardinality(ImmutableRoaringBitmap... bitmaps) {
    long[] words = new long[1024];
    int minKey = Character.MAX_VALUE;
    int maxKey = Character.MIN_VALUE;
    final int n = bitmaps.length;
    final int[] sizes = new int[n];
    for (int b = 0; b < n; b++) {
      ImmutableRoaringBitmap bitmap = bitmaps[b];
      final int size = bitmap.highLowContainer.size();
      sizes[b] = size;
      for (int i = 0; i < size; i++) {
        char key = bitmap.highLowContainer.getKeyAtIndex(i);
        words[key >>> 6] |= 1L << key;
        minKey = Math.min(minKey, key);
        maxKey = Math.max(maxKey, key);
      }
    }
    int numKeys = Util.cardinalityInBitmapRange(words, minKey, maxKey + 1);
    char[] keys = BitSetUtil.arrayContainerBufferOf(0, words.length, numKeys, words);

    LongBuffer longBuffer = LongBuffer.wrap(words);
    // per-bitmap cursor: keys are visited in ascending order, so each bitmap's
    // next unvisited key is the only candidate match (no binary search needed)
    final int[] pos = new int[n];
    int cardinality = 0;
    for (char key : keys) {
      Arrays.fill(words, 0);
      MappeableContainer tmp = new MappeableBitmapContainer(longBuffer, -1);
      for (int b = 0; b < n; b++) {
        int p = pos[b];
        if (p >= sizes[b]) {
          continue;
        }
        ImmutableRoaringBitmap bitmap = bitmaps[b];
        if (bitmap.highLowContainer.getKeyAtIndex(p) != key) {
          continue;
        }
        pos[b] = p + 1;
        MappeableContainer container = bitmap.highLowContainer.getContainerAtIndex(p);
        MappeableContainer or = tmp.lazyIOR(container);
        if (or != tmp) {
          tmp = or;
        }
      }
      cardinality += tmp.repairAfterLazy().getCardinality();
    }
    return cardinality;
  }

