        // Empty bucket: nothing to transfer or expire
        if (limit <= 0) {
          return 0;
        }
        continue;
      }
      transfer(sentinel, pending);
      try {
        @Var Node<K, V> node;
        while ((node = pending.getNextInVariableOrder()) != pending) {
          deschedule(node);
