private boolean parse1(CharSequence txt, int start, int end) {
    int i = start;
    while (i < end) {
        // Skip delimiters
        while (i < end && isDelim(txt.charAt(i))) {
            i++;
        }
        if (i >= end) {
            break;
        }
        int tokenStart = i;
        // Scan token until next delimiter or end
        while (i < end && !isDelim(txt.charAt(i))) {
            i++;
        }
        // token is txt[tokenStart,i)
        if (parseToken(txt, tokenStart, i)) {
            return true;
        }
    }
    return false;
}

