public static <R extends MutableIntCollection, T> R collectInt(
            T[] items,
            int size,
            IntFunction<? super T> intFunction,
            R target)
    {
        // Fast‑path for empty range
        if (size <= 0)
        {
            return target;
        }
        // Cache locals to avoid repeated field reads
        final IntFunction<? super T> fn = intFunction;
        final R result = target;
        int i = 0;
        while (i < size)
        {
            result.add(fn.intValueOf(items[i]));
            i++;
        }
        return result;
    }

