        // Cache parameters in locals to aid JIT optimizations and reduce repeated bounds checks
        T[] a = array;
        int end = size;
        Function<? super T, ? extends V> fn = function;
        R map = target;
        int i = 0;
        while (i < end) {
            T item = a[i];
            i++;
            map.put(fn.valueOf(item), item);
        }
        return map;
    }

