protected final void release(H handle) {
    Thread owner = this.owner;
    // Fast path: same thread and batch has space
    if (owner == Thread.currentThread() && batchSize < batch.length) {
        batch[batchSize++] = handle;
        return;
    }
    // If the owner thread has been terminated, discard the pool
    if (owner != null && isTerminated(owner)) {
        pooledHandles = null;
        this.owner = null;
        return;
    }
    // Fallback: offer to the shared queue if it exists
    MessagePassingQueue<H> handles = pooledHandles;
    if (handles != null) {
        handles.relaxedOffer(handle);
    }
}

