            if (digits == 0) {
                return false; // no digits between separators
            }
            if (part == 0) {
                h = value;
            } else if (part == 1) {
                m = value;
            } else {
                return false; // more than two ':'
            }
            part++;
            value = 0;
            digits = 0;
        } else {
            return false; // invalid character
        }
    }

    // after loop we must have seconds part
    if (digits == 0) {
        return false;
    }
    s = value;

    if (h >= 0 && m >= 0 && s >= 0) {
        hours = h;
        minutes = m;
        seconds = s;
        return true;
    }
    return false;
}

